"""Build the self-contained focused top-model overnight dashboard."""
from __future__ import annotations

import csv
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent
OUT = ROOT / "research" / "overnight_equities" / "focused_top30"


def read_csv(path: Path) -> list[dict]:
    if not path.exists():
        return []
    with path.open(encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Focused overnight paper replay</title><style>
:root{--bg:#07111f;--panel:#102039;--line:#2b405f;--text:#eaf2ff;--muted:#a8b7cf;--green:#42d6a0;--red:#ff7889;--amber:#ffd166;--blue:#79acff;--purple:#c69cff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#06101d,#0c1930 58%,#111c33);color:var(--text);font:14px/1.5 -apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif}main{max-width:1320px;margin:auto;padding:34px 22px 72px}.eyebrow{color:var(--blue);text-transform:uppercase;letter-spacing:.15em;font-size:11px;font-weight:700}h1{font-size:39px;line-height:1.08;margin:8px 0 10px;letter-spacing:-.035em}h2{font-size:18px;margin:0 0 12px}.muted{color:var(--muted)}.banner{border:1px solid #9c712c;background:#2a2115;border-radius:12px;padding:15px 18px;margin:22px 0}.pill{display:inline-block;background:#70451c;color:var(--amber);border-radius:999px;padding:3px 9px;font-size:11px;font-weight:700;letter-spacing:.06em}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:20px 0}.controls select{background:#0b172b;color:var(--text);border:1px solid var(--line);padding:9px 11px;border-radius:8px}.cards{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:16px 0}.card,.panel{background:rgba(16,32,57,.9);border:1px solid var(--line);border-radius:12px;padding:16px}.card small{display:block;color:var(--muted);font-size:11px}.card strong{display:block;font-size:24px;margin:4px 0}.positive{color:var(--green)}.negative{color:var(--red)}.amber{color:var(--amber)}.grid{display:grid;grid-template-columns:1.6fr .8fr;gap:16px}.chartbox{height:410px}.chartbox canvas{width:100%;height:100%}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:940px}th,td{padding:9px 10px;border-bottom:1px solid #223651;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.05em}td:first-child{font-weight:600}.signal{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #223651;padding:10px 0}.signal:last-child{border-bottom:0}.tag{color:var(--blue);font-weight:700}.legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:8px;color:var(--muted);font-size:12px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.sources{display:flex;gap:10px;flex-wrap:wrap}.sources a{color:#9fc2ff}.footer{color:var(--muted);font-size:12px;margin-top:28px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}h1{font-size:30px}}
</style></head><body><main><div class="eyebrow">Trading Lab · Focused paper research</div><h1>Top 30% only: overnight stock replay</h1><p class="muted">Two model families were frozen from the broad study's validation ranking, then replayed over two adjacent 90-session windows. The focused portfolio allocates 25% to each model and keeps 50% in cash.</p><div class="banner"><span class="pill">HISTORICAL SHADOW REPLAY · NO ORDERS</span><div style="margin-top:8px">This visual shows what the selected rules would have done using daily split/dividend-adjusted bars. It does not include quote-level spreads or news. The next step is an Alpaca paper-forward run with authenticated quotes and the news gate.</div></div><div class="controls"><label>Window <select id="window"></select></label><label>Chart <select id="chartMode"><option value="portfolio">Focused portfolio</option><option value="models">Selected models</option></select></label></div><div class="cards"><div class="card"><small>Frozen selection</small><strong id="selected">—</strong><span class="muted">of five models</span></div><div class="card"><small>Recent 90-session return</small><strong id="recentReturn">—</strong><span class="muted">50% total allocation</span></div><div class="card"><small>Recent max drawdown</small><strong id="recentDD">—</strong><span class="muted">portfolio equity</span></div><div class="card"><small>Prior 90-session return</small><strong id="priorReturn">—</strong><span class="muted">same frozen rules</span></div><div class="card"><small>Latest research picks</small><strong id="latest">—</strong><span class="muted">no next-session exit yet</span></div></div><div class="grid"><section class="panel"><h2>Equity curve</h2><div class="chartbox"><canvas id="chart" width="1100" height="400"></canvas></div><div class="legend"><span><i class="dot" style="background:#79acff"></i>Focused portfolio</span><span><i class="dot" style="background:#42d6a0"></i>Overnight momentum</span><span><i class="dot" style="background:#c69cff"></i>Intraday reversal</span></div><div id="chartNote" class="muted" style="margin-top:8px"></div></section><section class="panel"><h2>Latest evening screen</h2><div id="signals"></div><p class="muted" style="margin-top:14px">These are the last complete-session rankings. 2026-09-18 was followed by a weekend, so there is no exit bar and this is not an order instruction.</p></section></div><section class="panel" style="margin-top:16px"><h2>Selected model and portfolio results</h2><div class="tablewrap"><table><thead><tr><th>Window</th><th>Model</th><th>Return</th><th>Max DD</th><th>Win rate</th><th>Profit factor</th><th>Sharpe</th><th>Bootstrap lower</th><th>Allocation</th></tr></thead><tbody id="summary"></tbody></table></div></section><section class="panel" style="margin-top:16px"><h2>Cost and allocation stress</h2><div class="tablewrap"><table><thead><tr><th>Window</th><th>Scenario</th><th>Return</th><th>Max DD</th><th>Win rate</th><th>Profit factor</th><th>Bootstrap lower</th></tr></thead><tbody id="stress"></tbody></table></div></section><section class="panel" style="margin-top:16px"><h2>How the cut was made</h2><p class="muted">The broad study produced five model families. I ranked them by validation quality, selected ceil(5 × 30%) = 2 models, and froze that choice before looking at the two replay windows. The selected models are <b>overnight momentum</b> and <b>intraday reversal into the close</b>. The historical run uses 5 bps adverse slippage per side and zero commission. A doubled-cost row uses 10 bps per side.</p><div class="tablewrap"><table><thead><tr><th>Validation rank</th><th>Model</th><th>Validation return</th><th>Validation DD</th><th>Quality</th><th>Selected</th></tr></thead><tbody id="selection"></tbody></table></div></section><section class="panel" style="margin-top:16px"><h2>Next paper-forward step</h2><p class="muted">With Alpaca credentials configured, run <code>python3 overnight_daily.py --selection top30</code> after the close. It writes a news-gated signal and submits no order by default. A quote-aware 90-session paper ledger is the promotion test; this historical visual is only the baseline.</p><div class="sources"><a href="README.md">Focused README</a><a href="FOCUSED_PAPER_FORWARD.md">Paper-forward plan</a><a href="selection.json">Frozen selection JSON</a><a href="model_daily.csv">Model daily CSV</a><a href="portfolio_daily.csv">Portfolio daily CSV</a><a href="trade_log.csv">Trade log</a><a href="decision_log.csv">Decision log</a><a href="stress.csv">Stress CSV</a></div></section><div class="footer">$10,000 paper account · fixed liquid universe · no live orders · historical evidence only</div></main><script>
const DATA=__DATA__;const $=id=>document.getElementById(id);const pct=x=>Number(x).toFixed(2)+'%';const cls=x=>Number(x)>=0?'positive':'negative';const names=Object.fromEntries(DATA.selection.all_validation_candidates.map(x=>[x.model,x.name]));const selected=DATA.selection.selected_models.map(x=>x.model);const colors={focused_portfolio:'#79acff',overnight_momentum:'#42d6a0',overnight_reversal:'#c69cff'};const summary=DATA.summary;const stress=DATA.stress;const modelDaily=DATA.model_daily;const portfolioDaily=DATA.portfolio_daily;const fmt=x=>Number.isFinite(Number(x))?Number(x).toFixed(2):'—';
function srow(window,model){return summary.find(x=>x.window===window&&x.model===model)}function renderCards(){const rr=srow('recent_90','focused_portfolio'),pr=srow('prior_90','focused_portfolio');$('selected').textContent=selected.length+' / '+DATA.selection.candidate_count;$('recentReturn').textContent=pct(rr.return_pct);$('recentReturn').className=rr.return_pct>=0?'positive':'';$('recentDD').textContent=pct(-rr.max_drawdown_pct);$('recentDD').className='negative';$('priorReturn').textContent=pct(pr.return_pct);$('priorReturn').className=pr.return_pct>=0?'positive':'';$('latest').textContent=DATA.latest_signal.models.map(x=>x.symbol).join(' · ')}
function renderSignals(){ $('signals').innerHTML=DATA.latest_signal.models.map(x=>`<div class="signal"><span><b>${x.name}</b><br><span class="muted">score ${x.score==null?'—':Number(x.score).toFixed(3)} · regime ${x.market_regime?'on':'off'}</span></span><span class="tag">${x.symbol}</span></div>`).join('') }
function renderSummary(){ $('summary').innerHTML=summary.map(x=>`<tr><td>${x.window}</td><td>${x.name}</td><td class="${cls(x.return_pct)}">${pct(x.return_pct)}</td><td>${pct(-x.max_drawdown_pct)}</td><td>${fmt(x.win_rate_pct)}%</td><td>${Number(x.profit_factor).toFixed(2)}</td><td>${Number(x.daily_sharpe).toFixed(2)}</td><td class="negative">${pct(x.bootstrap_lower_95_pct)}</td><td>${fmt(Number(x.allocation)*100)}%</td></tr>`).join('') }
function renderStress(){ $('stress').innerHTML=stress.map(x=>`<tr><td>${x.window}</td><td>${x.scenario}</td><td class="${cls(x.return_pct)}">${pct(x.return_pct)}</td><td>${pct(-x.max_drawdown_pct)}</td><td>${fmt(x.win_rate_pct)}%</td><td>${Number(x.profit_factor).toFixed(2)}</td><td class="negative">${pct(x.bootstrap_lower_95_pct)}</td></tr>`).join('') }
function renderSelection(){ $('selection').innerHTML=DATA.selection.all_validation_candidates.map(x=>`<tr><td>${x.rank}</td><td>${x.name}</td><td class="${cls(x.validation_return_pct)}">${pct(x.validation_return_pct)}</td><td>${pct(-x.validation_drawdown_pct)}</td><td>${Number(x.validation_quality).toFixed(2)}</td><td class="${x.selected?'positive':'muted'}">${x.selected?'YES':'no'}</td></tr>`).join('') }
function draw(){const window=$('window').value,mode=$('chartMode').value,c=$('chart'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#102039';ctx.fillRect(0,0,w,h);const p=portfolioDaily.filter(x=>x.window===window);const datasets=[];if(mode==='portfolio'){datasets.push({label:'Focused portfolio',rows:p.map((x,i)=>({date:x.date,equity:Number(x.equity_after)})),color:colors.focused_portfolio})}else{for(const m of selected){const rows=modelDaily.filter(x=>x.window===window&&x.model===m);let eq=10000;const out=rows.map(x=>{eq*=1+Number(x.net_return_pct)/100;return {date:x.date,equity:eq}});datasets.push({label:names[m],rows:out,color:colors[m]||'#fff'})}}if(!datasets.length||!datasets[0].rows.length){$('chartNote').textContent='No chart rows';return}const allVals=datasets.flatMap(d=>d.rows.map(x=>x.equity));const lo=Math.min(...allVals),hi=Math.max(...allVals),L=64,R=20,T=20,B=35,X=i=>L+i*(w-L-R)/Math.max(1,datasets[0].rows.length-1),Y=v=>T+(hi-v)*(h-T-B)/Math.max(1e-9,hi-lo);ctx.strokeStyle='#2b405f';ctx.lineWidth=1;for(let j=0;j<5;j++){const yy=T+j*(h-T-B)/4;ctx.beginPath();ctx.moveTo(L,yy);ctx.lineTo(w-R,yy);ctx.stroke();ctx.fillStyle='#a8b7cf';ctx.font='11px Arial';ctx.fillText('$'+(hi-(hi-lo)*j/4).toFixed(0),4,yy+4)}for(const ds of datasets){ctx.strokeStyle=ds.color;ctx.lineWidth=2;ctx.beginPath();ds.rows.forEach((r,i)=>{const xx=X(i),yy=Y(r.equity);i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)});ctx.stroke()}const first=datasets[0].rows[0],last=datasets[0].rows.at(-1);ctx.fillStyle='#a8b7cf';ctx.font='11px Arial';ctx.fillText(first.date,L,h-10);ctx.fillText(last.date,w-102,h-10);const r=srow(window,'focused_portfolio');$('chartNote').textContent=`${window} · ${p.length} sessions · portfolio return ${pct(r.return_pct)} · range $${lo.toFixed(0)}–$${hi.toFixed(0)}`}
for(const w of ['prior_90','recent_90'])$('window').insertAdjacentHTML('beforeend',`<option value="${w}">${w.replace('_',' ')}</option>`);$('window').value='recent_90';$('window').onchange=draw;$('chartMode').onchange=draw;renderCards();renderSignals();renderSummary();renderStress();renderSelection();draw();
</script></body></html>'''


def main() -> None:
    report = json.loads((OUT / "results.json").read_text(encoding="utf-8"))
    report["model_daily"] = read_csv(OUT / "model_daily.csv")
    report["portfolio_daily"] = read_csv(OUT / "portfolio_daily.csv")
    report["summary"] = read_csv(OUT / "summary.csv")
    report["stress"] = read_csv(OUT / "stress.csv")
    page = HTML.replace("__DATA__", json.dumps(report, separators=(",", ":")))
    (OUT / "index.html").write_text(page, encoding="utf-8")
    print(OUT / "index.html")


if __name__ == "__main__":
    main()
